from functools import singledispatch

def integer_decimal(value):
    value = int.__index__(value)
    if value == 0:
        return '0'
    negative = value < 0
    value = abs(value)
    chunks = []
    while value:
        value, chunk = divmod(value, 10**9)
        chunks.append(chunk)
    result = str(chunks[-1]) + ''.join(format(chunk, '09d')
                                      for chunk in reversed(chunks[:-1]))
    return '-'+result if negative else result

@singledispatch
def render(value):
    raise TypeError('unsupported')

@render.register(int)
def _(value):
    return integer_decimal(value)

